/* Real C host for the Linux AMD64 shared libraries generated by `mio build --shared`.
 * Usage: host <directory-with-libs> <suite>   suites: math bytes text collections std multi stress reload
 * Every check prints "PASS name" or "FAIL name (line)"; the exit status is 1 when any check failed. */
#define _GNU_SOURCE
#include <dlfcn.h>
#include <limits.h>
#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int failures;
#define CHECK(name, cond) do { if (cond) printf("PASS %s\n", name); else { printf("FAIL %s (line %d)\n", name, __LINE__); failures++; } } while (0)

static void *open_lib(const char *dir, const char *file) {
    char path[4096];
    snprintf(path, sizeof path, "%s/%s", dir, file);
    dlerror();
    void *handle = dlopen(path, RTLD_NOW | RTLD_LOCAL);
    if (!handle) { printf("FAIL dlopen %s: %s\n", file, dlerror()); failures++; }
    return handle;
}
static void *sym(void *handle, const char *name) {
    dlerror();
    void *fn = dlsym(handle, name);
    const char *error = dlerror();
    if (error || !fn) { printf("FAIL dlsym %s: %s\n", name, error ? error : "NULL"); failures++; return NULL; }
    return fn;
}
/* Declares a local function pointer named after the exported symbol. */
#define FN(handle, ret, name, ...) ret (*name)(__VA_ARGS__) = (ret (*)(__VA_ARGS__))sym(handle, #name)

__asm__(
    ".text\n.globl regcheck\n.type regcheck, @function\nregcheck:\n"
    "  push %rbp\n  push %rbx\n  push %r12\n  push %r13\n  push %r14\n  push %r15\n  sub $8, %rsp\n"
    "  mov %rdi, %rax\n"
    "  movabs $0x1111111111111111, %rbx\n"
    "  movabs $0x2222222222222222, %rbp\n"
    "  movabs $0x3333333333333333, %r12\n"
    "  movabs $0x4444444444444444, %r13\n"
    "  movabs $0x5555555555555555, %r14\n"
    "  movabs $0x6666666666666666, %r15\n"
    "  mov $7, %edi\n  mov $35, %esi\n  call *%rax\n"
    "  xor %ecx, %ecx\n  cmpl $42, %eax\n  je 1f\n  or $1, %ecx\n1:\n"
    "  movabs $0x1111111111111111, %rdx\n  cmp %rdx, %rbx\n  je 2f\n  or $0x2, %ecx\n2:\n"
    "  movabs $0x2222222222222222, %rdx\n  cmp %rdx, %rbp\n  je 3f\n  or $0x4, %ecx\n3:\n"
    "  movabs $0x3333333333333333, %rdx\n  cmp %rdx, %r12\n  je 4f\n  or $0x8, %ecx\n4:\n"
    "  movabs $0x4444444444444444, %rdx\n  cmp %rdx, %r13\n  je 5f\n  or $0x10, %ecx\n5:\n"
    "  movabs $0x5555555555555555, %rdx\n  cmp %rdx, %r14\n  je 6f\n  or $0x20, %ecx\n6:\n"
    "  movabs $0x6666666666666666, %rdx\n  cmp %rdx, %r15\n  je 7f\n  or $0x40, %ecx\n7:\n"
    "  mov %ecx, %eax\n  add $8, %rsp\n  pop %r15\n  pop %r14\n  pop %r13\n  pop %r12\n  pop %rbx\n  pop %rbp\n  ret\n"
    ".size regcheck, .-regcheck\n");
/* 0 = the call returned 42 and rbx, rbp, r12-r15 came back unchanged; otherwise a bit mask of the mismatches. */
extern int regcheck(int32_t (*fn)(int32_t, int32_t));

static void math_checks(void *h, const char *tag) {
    char label[160];
#define L(text) (snprintf(label, sizeof label, "%s %s", tag, text), label)
    FN(h, int32_t, mio_math_add, int32_t, int32_t);
    FN(h, int64_t, mio_math_mul64, int64_t, int64_t);
    FN(h, int64_t, mio_math_gcd, int64_t, int64_t);
    FN(h, int64_t, mio_math_lcm, int64_t, int64_t);
    FN(h, int32_t, mio_math_abs32, int32_t);
    FN(h, int64_t, mio_math_clamp64, int64_t, int64_t, int64_t);
    FN(h, int32_t, mio_math_max32, int32_t, int32_t);
    FN(h, double, mio_math_sqrt64, double);
    FN(h, float, mio_math_floor32, float);
    FN(h, double, mio_math_hypot_sq, double, double);
    FN(h, _Bool, mio_math_is_even, int64_t);
    FN(h, double, mio_math_dot10, int64_t, int64_t, int64_t, int64_t, int64_t, int64_t, int64_t, int64_t, double, double);
    if (!mio_math_add || !mio_math_dot10 || !mio_math_is_even || !mio_math_floor32) return;
    CHECK(L("add 10+20"), mio_math_add(10, 20) == 30);
    CHECK(L("add negative"), mio_math_add(-5, 2) == -3);
    CHECK(L("add int32 wraps"), mio_math_add(INT_MAX, 1) == INT_MIN);
    CHECK(L("mul64"), mio_math_mul64(3000000000LL, 3) == 9000000000LL);
    CHECK(L("gcd"), mio_math_gcd(84, 36) == 12);
    CHECK(L("lcm"), mio_math_lcm(21, 6) == 42);
    CHECK(L("abs32"), mio_math_abs32(-123) == 123 && mio_math_abs32(77) == 77);
    CHECK(L("clamp64"), mio_math_clamp64(50, 0, 10) == 10 && mio_math_clamp64(-5, 0, 10) == 0 && mio_math_clamp64(5, 0, 10) == 5);
    CHECK(L("max32"), mio_math_max32(-1, -2) == -1);
    CHECK(L("sqrt64"), fabs(mio_math_sqrt64(2.0) - 1.4142135623730951) < 1e-15);
    CHECK(L("floor32 float32"), mio_math_floor32(2.75f) == 2.0f && mio_math_floor32(-2.25f) == -3.0f);
    CHECK(L("hypot_sq float64"), mio_math_hypot_sq(3.0, 4.0) == 25.0);
    CHECK(L("is_even bool result"), mio_math_is_even(10) == 1 && mio_math_is_even(7) == 0);
    CHECK(L("dot10: 8 int regs/stack + 2 xmm"), mio_math_dot10(1, 2, 3, 4, 5, 6, 7, 8, 2.0, 0.5) == 72.5);
    CHECK(L("callee-saved rbx rbp r12-r15 preserved"), regcheck(mio_math_add) == 0);
#undef L
}

static void bytes_checks(void *h, const char *tag) {
    char label[160];
#define L(text) (snprintf(label, sizeof label, "%s %s", tag, text), label)
    FN(h, int32_t, mio_bytes_new, int32_t);
    FN(h, int32_t, mio_bytes_write_byte, int32_t, uint8_t);
    FN(h, int64_t, mio_bytes_len, int32_t);
    FN(h, int32_t, mio_bytes_get, int32_t, int64_t);
    FN(h, int64_t, mio_bytes_index, int32_t, uint8_t);
    FN(h, uint32_t, mio_bytes_adler32, int32_t);
    FN(h, int32_t, mio_bytes_free, int32_t);
    if (!mio_bytes_new || !mio_bytes_free || !mio_bytes_adler32) return;
    int32_t a = mio_bytes_new(16);
    int32_t b = mio_bytes_new(0);
    CHECK(L("two distinct handles"), a > 0 && b > 0 && a != b);
    const char *text = "Wikipedia";
    for (const char *p = text; *p; p++) mio_bytes_write_byte(a, (uint8_t)*p);
    CHECK(L("len"), mio_bytes_len(a) == 9 && mio_bytes_len(b) == 0);
    CHECK(L("get"), mio_bytes_get(a, 0) == 'W' && mio_bytes_get(a, 8) == 'a' && mio_bytes_get(a, 9) == -2);
    CHECK(L("index"), mio_bytes_index(a, 'k') == 2 && mio_bytes_index(a, 'z') == -1);
    CHECK(L("adler32 of Wikipedia == 0x11E60398"), mio_bytes_adler32(a) == 0x11E60398u);
    CHECK(L("uint8 argument 255 stays 255"), mio_bytes_write_byte(b, 255) == 1 && mio_bytes_get(b, 0) == 255);
    CHECK(L("free then reuse is rejected"), mio_bytes_free(a) == 0 && mio_bytes_len(a) == -1 && mio_bytes_free(a) == -1);
    CHECK(L("invalid handle"), mio_bytes_len(0) == -1 && mio_bytes_len(9999) == -1 && mio_bytes_write_byte(-3, 1) == -1);
    mio_bytes_free(b);
#undef L
}

static int32_t text_make(int32_t (*newf)(void), int32_t (*push)(int32_t, uint8_t), const char *s) {
    int32_t t = newf();
    for (; *s; s++) push(t, (uint8_t)*s);
    return t;
}
static void text_checks(void *h, const char *tag) {
    char label[160];
#define L(text) (snprintf(label, sizeof label, "%s %s", tag, text), label)
    FN(h, int32_t, mio_text_new, void);
    FN(h, int32_t, mio_text_push_byte, int32_t, uint8_t);
    FN(h, int64_t, mio_text_byte_len, int32_t);
    FN(h, int64_t, mio_text_rune_count, int32_t);
    FN(h, _Bool, mio_text_is_utf8, int32_t);
    FN(h, int32_t, mio_text_has_prefix, int32_t, int32_t);
    FN(h, int64_t, mio_text_index, int32_t, int32_t);
    FN(h, int64_t, mio_text_count_vowels, int32_t);
    FN(h, int32_t, mio_text_free, int32_t);
    if (!mio_text_new || !mio_text_push_byte || !mio_text_free) return;
    int32_t hello = text_make(mio_text_new, mio_text_push_byte, "Hello, Mio shared world");
    int32_t pre = text_make(mio_text_new, mio_text_push_byte, "Hello");
    int32_t pat = text_make(mio_text_new, mio_text_push_byte, "shared");
    int32_t utf = text_make(mio_text_new, mio_text_push_byte, "\xe6\x97\xa5\xe6\x9c\xac\xe8\xaa\x9e!");
    int32_t bad = text_make(mio_text_new, mio_text_push_byte, "\xff\xfe");
    CHECK(L("byte_len"), mio_text_byte_len(hello) == 23);
    CHECK(L("rune_count ascii"), mio_text_rune_count(hello) == 23);
    CHECK(L("rune_count utf-8 (3 kanji + !)"), mio_text_rune_count(utf) == 4 && mio_text_byte_len(utf) == 10);
    CHECK(L("is_utf8"), mio_text_is_utf8(utf) && !mio_text_is_utf8(bad));
    CHECK(L("invalid utf-8 reported (-3)"), mio_text_rune_count(bad) == -3);
    CHECK(L("has_prefix"), mio_text_has_prefix(hello, pre) == 1 && mio_text_has_prefix(pre, hello) == 0);
    CHECK(L("index"), mio_text_index(hello, pat) == 11 && mio_text_index(hello, utf) == -1);
    CHECK(L("count_vowels"), mio_text_count_vowels(hello) == 7);
    CHECK(L("free"), mio_text_free(hello) == 0 && mio_text_byte_len(hello) == -1);
#undef L
}

static void collections_checks(void *h, const char *tag) {
    char label[160];
#define L(text) (snprintf(label, sizeof label, "%s %s", tag, text), label)
    FN(h, int32_t, mio_collections_new, void);
    FN(h, int64_t, mio_collections_push, int32_t, int64_t);
    FN(h, int64_t, mio_collections_len, int32_t);
    FN(h, int64_t, mio_collections_get, int32_t, int64_t, int64_t);
    FN(h, int64_t, mio_collections_sum, int32_t);
    FN(h, _Bool, mio_collections_contains, int32_t, int64_t);
    FN(h, int32_t, mio_collections_sort, int32_t);
    FN(h, int32_t, mio_collections_free, int32_t);
    if (!mio_collections_new || !mio_collections_push || !mio_collections_free) return;
    int32_t s = mio_collections_new();
    int64_t values[] = {5, -3, 9, 0, 9223372036854775000LL, 2, -3};
    for (size_t i = 0; i < sizeof values / sizeof *values; i++) mio_collections_push(s, values[i]);
    CHECK(L("len"), mio_collections_len(s) == 7);
    CHECK(L("get with fallback"), mio_collections_get(s, 2, -1) == 9 && mio_collections_get(s, 99, -77) == -77);
    CHECK(L("contains"), mio_collections_contains(s, 0) && !mio_collections_contains(s, 4));
    CHECK(L("sort"), mio_collections_sort(s) == 0 && mio_collections_get(s, 0, 1) == -3 && mio_collections_get(s, 1, 1) == -3 &&
        mio_collections_get(s, 6, 1) == 9223372036854775000LL && mio_collections_get(s, 3, 1) == 2);
    CHECK(L("sum (large int64)"), mio_collections_sum(s) == 9223372036854775000LL + 10);
    CHECK(L("free"), mio_collections_free(s) == 0 && mio_collections_len(s) == -1);
#undef L
}

/* The collector runs inside the library (threshold 32 MiB): churn well past it and check that live data survives. */
static void stress_checks(void *h) {
    FN(h, int32_t, mio_collections_new, void);
    FN(h, int64_t, mio_collections_push, int32_t, int64_t);
    FN(h, int64_t, mio_collections_sum, int32_t);
    FN(h, int32_t, mio_collections_free, int32_t);
    FN(h, int64_t, mio_collections_get, int32_t, int64_t, int64_t);
    if (!mio_collections_new || !mio_collections_push || !mio_collections_sum || !mio_collections_free || !mio_collections_get) return;
    int32_t keeper = mio_collections_new();
    for (int64_t i = 0; i < 1000; i++) mio_collections_push(keeper, i);
    int ok = 1;
    for (int round = 0; round < 400 && ok; round++) {
        int32_t t = mio_collections_new();
        int64_t expected = 0;
        for (int64_t i = 0; i < 20000; i++) { mio_collections_push(t, i * 3); expected += i * 3; }
        ok = mio_collections_sum(t) == expected && mio_collections_free(t) == 0;
    }
    CHECK("stress: 400 rounds x 20000 pushes (~hundreds of MiB allocated) stay correct", ok);
    CHECK("stress: long-lived data survives the collections", mio_collections_sum(keeper) == 499500 && mio_collections_get(keeper, 999, -1) == 999);
    mio_collections_free(keeper);
}

int main(int argc, char **argv) {
    if (argc != 3) { fprintf(stderr, "usage: %s <lib-dir> <suite>\n", argv[0]); return 2; }
    const char *dir = argv[1], *suite = argv[2];
    if (!strcmp(suite, "math")) { void *h = open_lib(dir, "libmio_math.so"); if (h) { math_checks(h, "math"); CHECK("math dlclose", dlclose(h) == 0); } }
    else if (!strcmp(suite, "bytes")) { void *h = open_lib(dir, "libmio_bytes.so"); if (h) { bytes_checks(h, "bytes"); CHECK("bytes dlclose", dlclose(h) == 0); } }
    else if (!strcmp(suite, "text")) { void *h = open_lib(dir, "libmio_text.so"); if (h) { text_checks(h, "text"); CHECK("text dlclose", dlclose(h) == 0); } }
    else if (!strcmp(suite, "collections")) { void *h = open_lib(dir, "libmio_collections.so"); if (h) { collections_checks(h, "collections"); CHECK("collections dlclose", dlclose(h) == 0); } }
    else if (!strcmp(suite, "std")) {
        void *h = open_lib(dir, "libmio_std.so");
        if (h) {
            math_checks(h, "std"); bytes_checks(h, "std"); text_checks(h, "std"); collections_checks(h, "std");
            CHECK("std dlclose", dlclose(h) == 0);
        }
    } else if (!strcmp(suite, "multi")) {
        /* all four independent libraries and the aggregate loaded at the same time; each owns a private runtime. */
        void *m = open_lib(dir, "libmio_math.so"), *b = open_lib(dir, "libmio_bytes.so"), *t = open_lib(dir, "libmio_text.so");
        void *c = open_lib(dir, "libmio_collections.so"), *s = open_lib(dir, "libmio_std.so");
        if (m && b && t && c && s) {
            math_checks(m, "multi/math"); bytes_checks(b, "multi/bytes"); text_checks(t, "multi/text"); collections_checks(c, "multi/collections");
            math_checks(s, "multi/std"); bytes_checks(s, "multi/std"); text_checks(s, "multi/std"); collections_checks(s, "multi/std");
            /* independent state: a handle made in the aggregate means nothing to the stand-alone library */
            FN(s, int32_t, mio_collections_new, void);
            FN(s, int64_t, mio_collections_push, int32_t, int64_t);
            FN(c, int64_t, mio_collections_len, int32_t);
            int32_t hs = mio_collections_new();
            mio_collections_push(hs, 1);
            CHECK("multi: runtimes are private per library", mio_collections_len(hs) == 1 || mio_collections_len(hs) == -1);
            CHECK("multi: dlclose in a different order", dlclose(t) == 0 && dlclose(s) == 0 && dlclose(m) == 0 && dlclose(c) == 0 && dlclose(b) == 0);
        }
    } else if (!strcmp(suite, "stress")) {
        void *h = open_lib(dir, "libmio_collections.so");
        if (h) { stress_checks(h); CHECK("stress dlclose", dlclose(h) == 0); }
        void *s = open_lib(dir, "libmio_std.so");
        if (s) { stress_checks(s); CHECK("stress (aggregate) dlclose", dlclose(s) == 0); }
    } else if (!strcmp(suite, "reload")) {
        /* dlclose followed by dlopen starts a fresh runtime */
        for (int i = 0; i < 3; i++) {
            void *h = open_lib(dir, "libmio_math.so");
            if (!h) break;
            math_checks(h, "reload");
            if (dlclose(h) != 0) { printf("FAIL reload dlclose\n"); failures++; }
        }
    } else { fprintf(stderr, "unknown suite %s\n", suite); return 2; }
    printf("%s: %s\n", suite, failures ? "FAILED" : "OK");
    return failures ? 1 : 0;
}
